#!/usr/bin/env python3
from pathlib import Path
import subprocess, wave, math, struct
out=Path('output'); out.mkdir(exist_ok=True)
audio=out/'narration.wav'; video=out/'AI時短ラボ_01_完成版.mp4'; sfx=out/'ui_sfx.wav'
if not audio.exists(): raise SystemExit('Missing narration')
